phase := 0
ticks := 0
k := 0
c := 0
b0 := 0
closed = (#Garage #ContactSensor).Contact
h = (#Clock).Hour
if (phase == 0) {
    if (h >= 22 and closed == false) {
        ticks = ticks + 1
        if (ticks > 6000) {
            b0 = (#Kitchen #Light).CurrentBrightness
            (#Kitchen #Light).MoveToBrightness(10, 0)
            phase = 1
            ticks = 0
            k = 0
            c = 0
        }
    } else {
        ticks = 0
    }
} else if (phase == 1) {
    ticks = ticks + 1
    if (closed == true) {
        (#Kitchen #Light).MoveToBrightness(b0, 0)
        c = c + 1
        ticks = 0
        if (c >= 7) {
            phase = 3
        } else {
            phase = 2
        }
    } else if (ticks == 5) {
        (#Kitchen #Light).MoveToBrightness(100, 0)
    } else if (ticks == 10) {
        k = k + 1
        ticks = 0
        if (k >= 10) {
            (#Kitchen #Light).MoveToBrightness(b0, 0)
            c = c + 1
            if (c >= 7) {
                phase = 3
            } else {
                phase = 2
            }
        } else {
            (#Kitchen #Light).MoveToBrightness(10, 0)
        }
    }
} else if (phase == 2) {
    ticks = ticks + 1
    if (ticks == 3000) {
        if (closed == true) {
            phase = 3
        } else {
            (#Kitchen #Light).MoveToBrightness(10, 0)
            phase = 1
            ticks = 0
            k = 0
        }
    }
}

